\begin{corollary}[Adaptive time step]
\label{cor:flux-timestep}
Let $\kappa_n := \lambda_{\max}(J_n,t_n)/\Phi_{\mathrm{total}}(J_n,t_n) \geq 1$ be the \emph{spatial stiffness ratio}, where $\lambda_{\max}(J_n,t_n) := \max_{\boldsymbol{x}\in J_n} w(\boldsymbol{x})$.
The \emph{total-flux rule} $\Delta t_n = \varepsilon_{\Delta t}/\Phi_{\mathrm{total}}(J_n,t_n)$ guarantees
\begin{equation}
\label{eq:dt-total}
\|\boldsymbol{\varepsilon}(t_{n+1})\|_1 \lesssim \Phi_{\mathrm{out}}(J_n,t_n)\,\Delta t_n \leq \varepsilon_{\Delta t},
\end{equation}
with expansion factor $\mu_n := \lambda_{\max}\,\Delta t_n = \kappa_n\,\varepsilon_{\Delta t}$.  The actual error-to-bound ratio $\Phi_{\mathrm{out}}/\Phi_{\mathrm{total}}$ depends on the expansion strategy:
\begin{itemize}
  \item \textbf{Stoichiometric expansion}: $\Phi_{\mathrm{out}} = 0$ after expansion, so the leading-order error vanishes and the true error is second-order $O(\varepsilon_{\Delta t}^2)$ (Corollary~\ref{cor:expansion-depth}).
  \item \textbf{Flux expansion} (threshold $\theta$): $\Phi_{\mathrm{out}} \leq \theta\,\Phi_{\mathrm{total}}$ (Corollary~\ref{cor:flux-expansion-bound}), tightening the error bound to $\theta\,\varepsilon_{\Delta t}$.
  \item \textbf{SSA expansion}: $\Phi_{\mathrm{out}} \leq \Phi_{\mathrm{total}}$; in steady state, dominant-reaction neighbors reside in $J$ and $\Phi_{\mathrm{out}} \ll \Phi_{\mathrm{total}}$ (Section~\ref{sec:results}).
\end{itemize}
\end{corollary}

\begin{proof}
By Theorem~\ref{thm:local-model-error} with $\Phi_{\mathrm{in}}(t_n) \approx 0$ (pruned states carry negligible probability at step start):
\[
\|\boldsymbol{\varepsilon}(t_{n+1})\|_1 \lesssim \Phi_{\mathrm{out}}(t_n)\,\Delta t_n.
\]
Since $\Phi_{\mathrm{out}} \leq \Phi_{\mathrm{total}}$ (Definition~\ref{def:boundary-outflux}) and $\Phi_{\mathrm{total}}\,\Delta t_n = \varepsilon_{\Delta t}$, both inequalities in~\eqref{eq:dt-total} follow.  The inflow term satisfies $\Phi_{\mathrm{in}}(t_n) \leq w_{\max}\,\alpha$ where $\alpha$ is the quantile parameter; choosing $\alpha$ small makes this negligible.  The expansion factor is $\mu_n = \lambda_{\max}\,\Delta t_n = \kappa_n\,\varepsilon_{\Delta t}$.
\end{proof}

\begin{corollary}[Flux expansion boundary outflux bound]
\label{cor:flux-expansion-bound}
For flux expansion with threshold $\theta \in (0,1)$, where neighbor $\boldsymbol{x}+\boldsymbol{\nu}_k$ is added to $J$ if and only if $\alpha_k(\boldsymbol{x})/w(\boldsymbol{x}) > \theta$, the boundary outflux satisfies
\begin{equation}
\label{eq:flux-expand-bound}
\Phi_{\mathrm{out}}(J_n, t_n) \leq \theta\,\Phi_{\mathrm{total}}(J_n, t_n).
\end{equation}
\end{corollary}

\begin{proof}
Each reaction $k$ whose neighbor $\boldsymbol{x}+\boldsymbol{\nu}_k$ is not added to $J$ satisfies $\alpha_k(\boldsymbol{x}) \leq \theta\,w(\boldsymbol{x})$ by the expansion criterion.  Its contribution to $\Phi_{\mathrm{out}}$ from state $\boldsymbol{x}$ is $\alpha_k(\boldsymbol{x})\,p(\boldsymbol{x}) \leq \theta\,w(\boldsymbol{x})\,p(\boldsymbol{x}) = \theta\,\Phi(\boldsymbol{x})$.  Summing over all states and excluded reactions gives $\Phi_{\mathrm{out}} \leq \theta\sum_{\boldsymbol{x}}p(\boldsymbol{x})w(\boldsymbol{x}) = \theta\,\Phi_{\mathrm{total}}$.
\end{proof}

