\begin{corollary}[Adaptive time step]
\label{cor:flux-timestep}
Let $\kappa_n := \lambda_{\max}(J_n,t_n)/\Phi_{\mathrm{total}}(J_n,t_n) \geq 1$ be the \emph{spatial stiffness ratio}, where $\lambda_{\max}(J_n,t_n) := \max_{\boldsymbol{x}\in J_n} w(\boldsymbol{x})$.
For any expansion strategy, the \emph{total-flux rule}
\begin{equation}
\label{eq:dt-total}
\Delta t_n = \frac{\varepsilon_{\Delta t}}{\Phi_{\mathrm{total}}(J_n,t_n)}
\end{equation}
guarantees $\|\boldsymbol{\varepsilon}(t_{n+1})\|_1 \lesssim \varepsilon_{\Delta t}$, with expansion factor $\mu_n := \lambda_{\max}\,\Delta t_n = \kappa_n\,\varepsilon_{\Delta t}$.
\end{corollary}

\begin{proof}
After renormalization $\Phi_{\mathrm{in}}(t_n) \approx 0$ (pruned states carry negligible probability; formally $\Phi_{\mathrm{in}} \leq w_{\max}\,\alpha$ with $\alpha$ small).  By Theorem~\ref{thm:local-model-error},
\[
\|\boldsymbol{\varepsilon}(t_{n+1})\|_1 \lesssim \Phi_{\mathrm{out}}(J_n,t_n)\,\Delta t_n \leq \Phi_{\mathrm{total}}(J_n,t_n)\,\Delta t_n = \varepsilon_{\Delta t},
\]
where the middle inequality uses $\Phi_{\mathrm{out}} \leq \Phi_{\mathrm{total}}$ (Definition~\ref{def:boundary-outflux}), which holds for any active set $J_n$ regardless of how it was constructed.
\end{proof}

